local MatMaker = {}
local PRODUCTS = {
    rush_mat = { name = "Tlatnik", rushCost = 5, time = 2, cost = 10, happiness = 1, description = "Preprosta tla iz rogoza." },
    straw_mat = { name = "Slamnata preproga", strawCost = 5, time = 2, cost = 8, happiness = 1, description = "Slamnata preproga." },
    woven_rug = { name = "Tkana preproga", woolCost = 5, threadCost = 2, time = 7, cost = 80, happiness = 4, description = "Volnena preproga." },
    felt_rug = { name = "Filc preproga", woolCost = 8, time = 5, cost = 60, happiness = 3, description = "Filcana volnena preproga." },
    silk_rug = { name = "Svilena preproga", silkCost = 5, threadCost = 3, time = 20, cost = 400, happiness = 10, prestige = 10, description = "Luksuzna svilena preproga." },
    royal_carpet = { name = "Kraljevski preproga", silkCost = 8, goldThreadCost = 3, woolCost = 5, time = 30, cost = 1000, happiness = 15, prestige = 25, description = "Najboljša preproga za kralja." },
}
local BUILDINGS = {
    workshop = { name = "Preprogarska delavnica", cost = { gold = 150, wood = 80 }, upkeep = 3, qualityBonus = 5 },
    rush_bed = { name = "Rogozničnik", cost = { gold = 80, wood = 30 }, upkeep = 1, rushProduction = 5 },
    weaving_loom = { name = "Statva za preproge", cost = { gold = 800, wood = 300, iron = 30 }, upkeep = 20, qualityBonus = 20 },
    royal_carpetry = { name = "Kraljevska preprogarna", cost = { gold = 3000, wood = 400, stone = 500, gold = 30 }, upkeep = 60, qualityBonus = 35, prestigeBonus = 15 },
}
MatMaker.rushStock = 15; MatMaker.strawStock = 15; MatMaker.woolStock = 10; MatMaker.threadStock = 8; MatMaker.silkStock = 3; MatMaker.goldThreadStock = 2
MatMaker.productStock = {}; MatMaker.buildings = {}; MatMaker.maker = nil; MatMaker.activeMaking = {}; MatMaker.totalProducts = 0; MatMaker.dayTimer = 0
function MatMaker.init() MatMaker.rushStock=15; MatMaker.strawStock=15; MatMaker.woolStock=10; MatMaker.threadStock=8; MatMaker.silkStock=3; MatMaker.goldThreadStock=2; MatMaker.productStock={}; MatMaker.buildings={}; MatMaker.maker=nil; MatMaker.activeMaking={}; MatMaker.totalProducts=0; MatMaker.dayTimer=0; print("[MatMaker] Royal Mat Maker & Floor Covering System initialized (6 products, 4 buildings)") end
function MatMaker.hireMaker(n,s) s=s or math.random(30,75); local c=150+s*3; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MatMaker.maker={name=n or ("Preprogar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Preprogar najet: %s (spretnost: %d)",MatMaker.maker.name,s),"success") end; return true end
function MatMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MatMaker.build(id) local ok,e=MatMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MatMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MatMaker.getQualityBonus() local b=0; for _,bd in ipairs(MatMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MatMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.rushCost and MatMaker.rushStock<(d.rushCost or 0) then return false,"Premalo rogoza" end; if d.strawCost and MatMaker.strawStock<(d.strawCost or 0) then return false,"Premalo slame" end; if d.woolCost and MatMaker.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.threadCost and MatMaker.threadStock<(d.threadCost or 0) then return false,"Premalo niti" end; if d.silkCost and MatMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.goldThreadCost and MatMaker.goldThreadStock<(d.goldThreadCost or 0) then return false,"Premalo zlatih niti" end; if #MatMaker.buildings==0 then return false,"Potrebna delavnica" end; if not MatMaker.maker then return false,"Potreben preprogar" end; return true end
function MatMaker.make(pt) local ok,e=MatMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.rushCost then MatMaker.rushStock=MatMaker.rushStock-d.rushCost end; if d.strawCost then MatMaker.strawStock=MatMaker.strawStock-d.strawCost end; if d.woolCost then MatMaker.woolStock=MatMaker.woolStock-d.woolCost end; if d.threadCost then MatMaker.threadStock=MatMaker.threadStock-d.threadCost end; if d.silkCost then MatMaker.silkStock=MatMaker.silkStock-d.silkCost end; if d.goldThreadCost then MatMaker.goldThreadStock=MatMaker.goldThreadStock-d.goldThreadCost end; local t=d.time; if MatMaker.maker then t=math.max(1,t-math.floor(MatMaker.maker.skill/12)) end; table.insert(MatMaker.activeMaking,{id="mat_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost,happiness=d.happiness or 0,prestige=d.prestige or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Tkanje: %s (%d dni)",d.name,t),"info") end; return true end
function MatMaker.completeMaking(m) local q=1.0+(MatMaker.getQualityBonus()/100); if MatMaker.maker then q=q+(MatMaker.maker.skill/200) end; q=math.min(2.0,q); MatMaker.productStock[m.productType]=(MatMaker.productStock[m.productType] or 0)+1; MatMaker.totalProducts=MatMaker.totalProducts+1; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness*q) end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if MatMaker.maker then MatMaker.maker.itemsMade=MatMaker.maker.itemsMade+1; if math.random()<0.15 then MatMaker.maker.skill=math.min(100,MatMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Preproga izdelana: %s (kakovost: %.1f)",m.productName,q),"success") end end
function MatMaker.update(dt) if not _G.state then return end; MatMaker.dayTimer=MatMaker.dayTimer+dt; if MatMaker.dayTimer>=30 then MatMaker.dayTimer=0; for i=#MatMaker.activeMaking,1,-1 do local m=MatMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MatMaker.completeMaking(m); table.remove(MatMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MatMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MatMaker.maker then tu=tu+4 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function MatMaker.getStats() return {rushStock=MatMaker.rushStock,woolStock=MatMaker.woolStock,silkStock=MatMaker.silkStock,productStock=MatMaker.productStock,numBuildings=#MatMaker.buildings,hasMaker=MatMaker.maker~=nil,makerName=MatMaker.maker and MatMaker.maker.name or "—",makerSkill=MatMaker.maker and MatMaker.maker.skill or 0,activeMaking=#MatMaker.activeMaking,totalProducts=MatMaker.totalProducts} end
return MatMaker
